///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        await scwin.setInit();
        scwin.contnId = $c.frame.path("../").fn_getContnId();
        if (scwin.contnId !== "input") {
            await scwin.listSync();
        } else {
            await scwin.setHeader();
            buttonSet.setInsertStatus();
        }
        const parentframeID = $c.stf.getQuery(frame.srcUrl, "frameID");
        if (parentframeID.indexOf('STF60000') !== -1) {
            btn_Save.hide();
            btn_Delete.hide();
        }
        tbox_wrtr_emp_nm.setValue(js_emp_nm);
        tbox_reg_dep_nm.setValue(js_dep_nm);
        tbox_wrt_ddtm.setValue($c.ut.cGetToday("yyyy-mm-dd hh:mm:ss"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60012.onpageload" });
    }
};

