/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (dts_fileList.getCellData(1, "fileInfo") === "") {
        dts_fileList.Reset();
    }
    if (await scwin.checkForm()) {
        let rtn = confirm('저장 하시겠습니까?');
        if (rtn === 1) {
            dts_issue.setCellData(1, "LIST_INVSTG_ISUE_TP_CD", cmb_IsueTp.getValue());
            dts_issue.setCellData(1, "REG_ID", js_emp_no);
            dts_issue.setCellData(1, "REG_DEP_CD", js_dep_cd);
            dts_issue.setCellData(1, "REG_DDTM", tbox_wrt_ddtm);
            const sbmOptions = {
                id : "sbm_trs_Save",
                action : "/ListIssueAdm.do",
                ref : "dts_issue,dts_issuedtl,dts_fileList",
                target : "trs_Save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

