 * @name indexingElasitcSearch
 * @description indexing Elasitc Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.indexingElasitcSearch = async function() {
    if (scwin.contnId === "input") {
        await scwin.getRecentContnId();
        await scwin.listSync();
    }
    list_invstg_isue_file(scwin.contnId);
};

/**
 * @method
 * @name setParam
 * @description set Param 처리
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const parentWin = $c.frame.path("../");
    const paramObj = parentWin.gParamObj;
    if (paramObj === undefined) return;
    txb_ISUR_CD.setValue(paramObj.param0);
    txb_BYCORP_SEQ.setValue(paramObj.param1);
    Q;
    txb_COM_NM.setValue(paramObj.param2);
};

/**
 * @method
 * @name getPar
 * @description Get checkBox DataSet
 * @param {String} param_contnId param_contnId
 * @param {*} param_dts1 param_dts1
 * @param {*} param_dts2 param_dts2
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function(param_contnId, param_dts1, param_dts2) {
    param_contnId = scwin.contnId;
    $c.stf.copyDataSet(dts_issuedtl, param_dts1);
    $c.stf.copyDataSet(dts_issuedtlyn, param_dts2);
};

/**
 * @method
 * @name setPar
 * @description Set checkBox DataSet
 * @param {*} param_dts1 param_dts1
 * @param {*} param_dts2 param_dts2
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(param_dts1, param_dts2) {
    $c.stf.copyDataSet(param_dts1, dts_issuedtlyn);
    $c.stf.copyDataSet(param_dts2, dts_issuedtl);
    dts_issuedtl.setBroadcast(false);
    for (i = 1; i <= dts_issuedtl.getRowCount(); i++) {
        dts_issuedtl.setCellData(i, "CONTN_ID", scwin.contnId);
    }
    dts_issuedtl.setBroadcast(true, true);
};
